ApexPages.Message shortMessage = new ApexPages.Message(ApexPages.Severity.ERROR, 'summary');
ApexPages.Message detailedMessage = new ApexPages.Message(ApexPages.Severity.INFO, 'summary', 'detail');
ApexPages.Message labeledMessage = new ApexPages.Message(ApexPages.Severity.WARNING, 'summary', 'detail', 'label');
Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
email.setSubject('cb183 subject');
email.setToAddresses(new List<String>{'cb183@example.test'});
Boolean result = shortMessage.getSeverity() == ApexPages.Severity.ERROR && shortMessage.getSummary() == 'summary' && detailedMessage.getDetail() == 'detail' && labeledMessage.getComponentLabel() == 'label' && ApexPages.Severity.CONFIRM != ApexPages.Severity.FATAL && email.getSubject() == 'cb183 subject' && email.getToAddresses().size() == 1;
System.debug(result);

